SELECT p.moca_aid,p.avg_dist,p.avg_dist_unc,p.moca_bsmdid,p.is_public FROM calc_banyan_sigma_model_properties p WHERE p.moca_bsmdid=(SELECT moca_bsmdid FROM moca_banyan_sigma_models WHERE adopted=1) AND (p.is_public=0 OR (p.is_public=1 AND NOT EXISTS (SELECT 1 FROM calc_banyan_sigma_model_properties private_p WHERE private_p.moca_aid=p.moca_aid AND private_p.moca_bsmdid=p.moca_bsmdid AND private_p.is_public=0)))
